29	// Span is the database representation of a span.
30	type Span struct {
31		TraceID       TraceID
32		SpanID        int64
33		ParentID      int64 // deprecated
34		OperationName string
35		Flags         int32
36		StartTime     int64 // microseconds since epoch
37		Duration      int64 // microseconds
38		Tags          []KeyValue
39		Logs          []Log
40		Refs          []SpanRef
41		Process       Process
42		ServiceName   string
43		SpanHash      int64
44	}
45	
46	// KeyValue is the UDT representation of a Jaeger KeyValue.
47	type KeyValue struct {
48		Key          string  `cql:"key"`
49		ValueType    string  `cql:"value_type"`
50		ValueString  string  `cql:"value_string" json:"value_string,omitempty"`
51		ValueBool    bool    `cql:"value_bool" json:"value_bool,omitempty"`
52		ValueInt64   int64   `cql:"value_long" json:"value_long,omitempty"`     // using more natural column name for Cassandra
53		ValueFloat64 float64 `cql:"value_double" json:"value_double,omitempty"` // using more natural column name for Cassandra
54		ValueBinary  []byte  `cql:"value_binary" json:"value_binary,omitempty"`
55	}
56	
57	func (t *KeyValue) compareValues(that *KeyValue) int {
58		switch t.ValueType {
59		case stringType:
60			return strings.Compare(t.ValueString, that.ValueString)
61		case boolType:
62			if t.ValueBool != that.ValueBool {
63				if !t.ValueBool {
64					return -1
65				}
66				return 1
67			}
68		case int64Type:
69			return int(t.ValueInt64 - that.ValueInt64)
70		case float64Type:
71			if t.ValueFloat64 != that.ValueFloat64 {
72				if t.ValueFloat64 < that.ValueFloat64 {
73					return -1
74				}
75				return 1
76			}
77		case binaryType:
78			return bytes.Compare(t.ValueBinary, that.ValueBinary)
79		default:
80			return -1 // theoretical case, not stating them equal but placing the base pointer before other
81		}
82		return 0
83	}
84	
85	func (t *KeyValue) Compare(that any) int {
86		if that == nil {
87			if t == nil {
88				return 0
89			}
90			return 1
91		}
92		that1, ok := that.(*KeyValue)
93		if !ok {
94			that2, ok := that.(KeyValue)
95			if !ok {
96				return 1
97			}
98			that1 = &that2
99		}
100		if that1 == nil {
101			if t == nil {
102				return 0
103			}
104			return 1
105		} else if t == nil {
106			return -1
107		}
108		if cmp := strings.Compare(t.Key, that1.Key); cmp != 0 {
109			return cmp
110		}
111		if cmp := strings.Compare(t.ValueType, that1.ValueType); cmp != 0 {
112			return cmp
113		}
114		return t.compareValues(that1)
115	}
116	
117	func (t *KeyValue) Equal(that any) bool {
118		return t.Compare(that) == 0
119	}
120	
121	func (t *KeyValue) AsString() string {
122		switch t.ValueType {
123		case stringType:
124			return t.ValueString
125		case boolType:
126			if t.ValueBool {
127				return "true"
128			}
129			return "false"
130		case int64Type:
131			return strconv.FormatInt(t.ValueInt64, 10)
132		case float64Type:
133			return strconv.FormatFloat(t.ValueFloat64, 'g', 10, 64)
134		case binaryType:
135			return hex.EncodeToString(t.ValueBinary)
136		default:
137			return "unknown type " + t.ValueType
138		}
139	}
140	
141	func SortKVs(kvs []KeyValue) {
142		sort.Slice(kvs, func(i, j int) bool {
143			return kvs[i].Compare(kvs[j]) < 0
144		})
145	}
146	
147	// Log is the UDT representation of a Jaeger Log.
148	type Log struct {
149		Timestamp int64      `cql:"ts"` // microseconds since epoch
150		Fields    []KeyValue `cql:"fields"`
151	}
152	
153	// SpanRef is the UDT representation of a Jaeger Span Reference.
154	type SpanRef struct {
155		RefType string  `cql:"ref_type"`
156		TraceID TraceID `cql:"trace_id"`
157		SpanID  int64   `cql:"span_id"`
158	}
159	
160	// Process is the UDT representation of a Jaeger Process.
161	type Process struct {
162		ServiceName string     `cql:"service_name"`
163		Tags        []KeyValue `cql:"tags"`
164	}
165	
166	// TagInsertion contains the items necessary to insert a tag for a given span
167	type TagInsertion struct {
168		ServiceName string
169		TagKey      string
170		TagValue    string
171	}
172	
173	func (t TagInsertion) String() string {
174		const uniqueTagDelimiter = ":"
175		var buffer bytes.Buffer
176		buffer.WriteString(t.ServiceName)
177		buffer.WriteString(uniqueTagDelimiter)
178		buffer.WriteString(t.TagKey)
179		buffer.WriteString(uniqueTagDelimiter)
180		buffer.WriteString(t.TagValue)
181		return buffer.String()
182	}
183	
184	// TraceIDFromDomain converts domain TraceID into serializable DB representation.
185	func TraceIDFromDomain(traceID model.TraceID) TraceID {
186		dbTraceID := TraceID{}
187		binary.BigEndian.PutUint64(dbTraceID[:8], uint64(traceID.High))
188		binary.BigEndian.PutUint64(dbTraceID[8:], uint64(traceID.Low))
189		return dbTraceID
190	}
