const (
	noServiceName    = "OTLPResourceNoServiceName"
	eventNameAttr    = "event"
	statusError      = "ERROR"
	statusOk         = "OK"
	tagError         = "error"
	tagW3CTraceState = "w3c.tracestate"
	tagHTTPStatusMsg = "http.status_message"
)

// ToDBModel translates internal trace data into the Cassandra DB model.
func ToDBModel(td ptrace.Traces) []dbmodel.Span {
	resourceSpans := td.ResourceSpans()

	if resourceSpans.Len() == 0 {
		return nil
	}

	var spans []dbmodel.Span
	for i := 0; i < resourceSpans.Len(); i++ {
		rs := resourceSpans.At(i)
		ilss := rs.ScopeSpans()
		if ilss.Len() == 0 {
			continue
		}
		process := resourceToDbProcess(rs.Resource())
		for j := 0; j < ilss.Len(); j++ {
			ils := ilss.At(j)
			ilSpans := ils.Spans()
			for k := 0; k < ilSpans.Len(); k++ {
				spans = append(spans, spanToDbSpan(ilSpans.At(k), ils.Scope(), process))
			}
		}
	}

	return spans
}

func resourceToDbProcess(resource pcommon.Resource) dbmodel.Process {
	process := dbmodel.Process{}
	attrs := resource.Attributes()
	if attrs.Len() == 0 {
		process.ServiceName = noServiceName
		return process
	}
	attrsCount := attrs.Len()
	if serviceName, ok := attrs.Get(otelsemconv.ServiceNameKey); ok {
		process.ServiceName = serviceName.Str()
		attrsCount--
	}
	if attrsCount == 0 {
		return process
	}

	tags := make([]dbmodel.KeyValue, 0, attrsCount)
	process.Tags = appendTagsFromResourceAttributes(tags, attrs)
	return process
}

func appendTagsFromResourceAttributes(dest []dbmodel.KeyValue, attrs pcommon.Map) []dbmodel.KeyValue {
	if attrs.Len() == 0 {
		return dest
	}

	for key, attr := range attrs.All() {
		if key == otelsemconv.ServiceNameKey {
			continue
		}
		dest = append(dest, attributeToDbTag(key, attr))
	}
	return dest
}

func appendTagsFromAttributes(dest []dbmodel.KeyValue, attrs pcommon.Map) []dbmodel.KeyValue {
	if attrs.Len() == 0 {
		return dest
	}
	for key, attr := range attrs.All() {
		dest = append(dest, attributeToDbTag(key, attr))
	}
	return dest
}

func attributeToDbTag(key string, attr pcommon.Value) dbmodel.KeyValue {
	tag := dbmodel.KeyValue{Key: key}
	switch attr.Type() {
	case pcommon.ValueTypeInt:
		tag.ValueType = dbmodel.Int64Type
		tag.ValueInt64 = attr.Int()
	case pcommon.ValueTypeBool:
		tag.ValueType = dbmodel.BoolType
		tag.ValueBool = attr.Bool()
	case pcommon.ValueTypeDouble:
		tag.ValueType = dbmodel.Float64Type
		tag.ValueFloat64 = attr.Double()
	case pcommon.ValueTypeBytes:
		tag.ValueType = dbmodel.BinaryType
		tag.ValueBinary = attr.Bytes().AsRaw()
	case pcommon.ValueTypeMap, pcommon.ValueTypeSlice:
		tag.ValueType = dbmodel.StringType
		tag.ValueString = attr.AsString()
	default:
		tag.ValueType = dbmodel.StringType
		tag.ValueString = attr.Str()
	}
	return tag
}

func spanToDbSpan(span ptrace.Span, scope pcommon.InstrumentationScope, process dbmodel.Process) dbmodel.Span {
	traceID := dbmodel.TraceID(span.TraceID())
	refs := makeDbReferences(span.Links(), spanIDToDbSpanID(span.ParentSpanID()), traceID)

	//nolint:gosec // G115
	startTime := int64(span.StartTimestamp()) / 1000
	//nolint:gosec // G115
	endTime := int64(span.EndTimestamp()) / 1000
	return dbmodel.Span{
		TraceID:       traceID,
		SpanID:        spanIDToDbSpanID(span.SpanID()),
		OperationName: span.Name(),
		Refs:          refs,
		StartTime:     startTime,
		Duration:      endTime - startTime,
		Tags:          getDbSpanTags(span, scope),
		Logs:          spanEventsToDbLogs(span.Events()),
		Process:       process,
		ServiceName:   process.ServiceName,
	}
}

func getDbSpanTags(span ptrace.Span, scope pcommon.InstrumentationScope) []dbmodel.KeyValue {
	var spanKindTag, statusCodeTag, statusMsgTag dbmodel.KeyValue
	var spanKindTagFound, statusCodeTagFound, statusMsgTagFound bool

	libraryTags, libraryTagsFound := getTagsFromInstrumentationLibrary(scope)

	tagsCount := span.Attributes().Len() + len(libraryTags)

	spanKindTag, spanKindTagFound = getTagFromSpanKind(span.Kind())
	if spanKindTagFound {
		tagsCount++
	}
	status := span.Status()
	statusCodeTag, statusCodeTagFound = getTagFromStatusCode(status.Code())
	if statusCodeTagFound {
		tagsCount++
	}

	statusMsgTag, statusMsgTagFound = getTagFromStatusMsg(status.Message())
	if statusMsgTagFound {
		tagsCount++
	}

	traceStateTags, traceStateTagsFound := getTagsFromTraceState(span.TraceState().AsRaw())
	if traceStateTagsFound {
		tagsCount += len(traceStateTags)
	}

	if tagsCount == 0 {
		return nil
	}

	tags := make([]dbmodel.KeyValue, 0, tagsCount)
	if libraryTagsFound {
		tags = append(tags, libraryTags...)
	}
	tags = appendTagsFromAttributes(tags, span.Attributes())
	if spanKindTagFound {
		tags = append(tags, spanKindTag)
	}
	if statusCodeTagFound {
		tags = append(tags, statusCodeTag)
	}
	if statusMsgTagFound {
		tags = append(tags, statusMsgTag)
	}
	if traceStateTagsFound {
		tags = append(tags, traceStateTags...)
	}
	return tags
}

func spanIDToDbSpanID(spanID pcommon.SpanID) int64 {
	//nolint:gosec // G115
	return int64(idutils.SpanIDToUInt64(spanID))
}

// makeDbReferences constructs DB span references based on parent span ID and span links.
// The parent span ID is used to add a child-of reference, _unless_ it is referenced from one of the links.
func makeDbReferences(links ptrace.SpanLinkSlice, parentSpanID int64, traceID dbmodel.TraceID) []dbmodel.SpanRef {
	refsCount := links.Len()
	if parentSpanID != 0 {
		refsCount++
	}

	if refsCount == 0 {
		return nil
	}

	refs := make([]dbmodel.SpanRef, 0, refsCount)

	// Put parent span ID at the first place because usually backends look for it
	// as the first child-of item in the dbmodel.SpanRef slice.
	if parentSpanID != 0 {
		refs = append(refs, dbmodel.SpanRef{
			TraceID: traceID,
			SpanID:  parentSpanID,
			RefType: dbmodel.ChildOf,
		})
	}

	for i := 0; i < links.Len(); i++ {
		link := links.At(i)
		linkTraceID := dbmodel.TraceID(link.TraceID())
		linkSpanID := spanIDToDbSpanID(link.SpanID())
		linkRefType := refTypeFromLink(link)
		if parentSpanID != 0 && linkTraceID == traceID && linkSpanID == parentSpanID {
			// We already added a reference to this span, but maybe with the wrong type, so override.
			refs[0].RefType = linkRefType
			continue
		}
		refs = append(refs, dbmodel.SpanRef{
			TraceID: linkTraceID,
			SpanID:  linkSpanID,
			RefType: linkRefType,
		})
	}

	return refs
}

