func extractScope(tags []dbmodel.KeyValue, scope pcommon.InstrumentationScope) []dbmodel.KeyValue {
	nameIdx := indexOfKey(tags, otelsemconv.AttributeOtelScopeName)
	if nameIdx == -1 {
		return tags
