package tracestore

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"go.opentelemetry.io/collector/pdata/pcommon"
	"go.opentelemetry.io/collector/pdata/ptrace"

	"github.com/jaegertracing/jaeger/internal/storage/v1/cassandra/spanstore/dbmodel"
	"github.com/jaegertracing/jaeger/internal/telemetry/otelsemconv"
)

func TestSpec_FromDBModel_Empty(t *testing.T) {
	td := FromDBModel(nil)
	assert.Equal(t, 0, td.ResourceSpans().Len())
	td = FromDBModel([]dbmodel.Span{})
	assert.Equal(t, 0, td.ResourceSpans().Len())
}

func TestSpec_FromDBModel_EmptyProcess(t *testing.T) {
	td := FromDBModel([]dbmodel.Span{{}})
	assert.Equal(t, 1, td.ResourceSpans().Len())
	assert.Equal(t, 0, td.ResourceSpans().At(0).Resource().Attributes().Len())
}

func TestSpec_dbSpansToSpans_SingleEntry(t *testing.T) {
	td := ptrace.NewTraces()
	dbSpansToSpans([]dbmodel.Span{{}}, td.ResourceSpans())
	assert.Equal(t, 1, td.ResourceSpans().Len())
}

func TestSpec_ToDBModel_Empty(t *testing.T) {
	assert.Empty(t, ToDBModel(ptrace.NewTraces()))

	// resource spans present but no scope spans
	td := ptrace.NewTraces()
	td.ResourceSpans().AppendEmpty()
	assert.Empty(t, ToDBModel(td))
}

func TestSpec_ToDBModel_EmptyAttributes(t *testing.T) {
	td := ptrace.NewTraces()
	ss := td.ResourceSpans().AppendEmpty().ScopeSpans().AppendEmpty()
	ss.Spans().AppendEmpty()
	spans := ToDBModel(td)
	assert.Len(t, spans, 1)
	assert.Empty(t, spans[0].Tags)
	assert.Equal(t, noServiceName, spans[0].Process.ServiceName)
}

func TestSpec_dbLogsToSpanEvents(t *testing.T) {
	logs := []dbmodel.Log{{Timestamp: 1485467191639875}}
	events := ptrace.NewSpanEventSlice()
	dbLogsToSpanEvents(logs, events)
	assert.Equal(t, int64(1485467191639875), int64(events.At(0).Timestamp()/1000))
}

func TestSpec_dbTagsToAttributes_Unknown(t *testing.T) {
	m := pcommon.NewMap()
	dbTagsToAttributes([]dbmodel.KeyValue{{Key: "k", ValueType: "weird"}}, m)
	v, _ := m.Get("k")
	assert.Equal(t, `<Unknown Jaeger TagType "weird">`, v.Str())
}

func TestSpec_getTagFromStatusCode(t *testing.T) {
	got, ok := getTagFromStatusCode(ptrace.StatusCodeError)
	assert.True(t, ok)
	assert.Equal(t, dbmodel.KeyValue{Key: tagError, ValueType: dbmodel.BoolType, ValueBool: true}, got)

	got, ok = getTagFromStatusCode(ptrace.StatusCodeOk)
	assert.True(t, ok)
	assert.Equal(t, dbmodel.KeyValue{Key: otelsemconv.OtelStatusCode, ValueType: dbmodel.StringType, ValueString: statusOk}, got)

	_, ok = getTagFromStatusCode(ptrace.StatusCodeUnset)
	assert.False(t, ok)
}

func TestSpec_getTagFromStatusMsg(t *testing.T) {
	_, ok := getTagFromStatusMsg("")
	assert.False(t, ok)
	got, ok := getTagFromStatusMsg("boom")
	assert.True(t, ok)
	assert.Equal(t, dbmodel.StringType, got.ValueType)
	assert.Equal(t, "boom", got.ValueString)
}

func TestSpec_spanToDbSpan_LinkRefFollowsFrom(t *testing.T) {
	td := ptrace.NewTraces()
	ss := td.ResourceSpans().AppendEmpty().ScopeSpans().AppendEmpty()
	span := ss.Spans().AppendEmpty()
	span.Links().AppendEmpty().Attributes().PutStr("k", "v")
	dbSpan := spanToDbSpan(span, ss.Scope(), dbmodel.Process{ServiceName: noServiceName})
	assert.Len(t, dbSpan.Refs, 1)
	assert.Equal(t, dbmodel.FollowsFrom, dbSpan.Refs[0].RefType)

	// no attributes -> empty tags
	span2 := ss.Spans().AppendEmpty()
	dbSpan2 := spanToDbSpan(span2, ss.Scope(), dbmodel.Process{ServiceName: noServiceName})
	assert.Empty(t, dbSpan2.Tags)
}

func TestSpec_resourceToDbProcess(t *testing.T) {
	td := ptrace.NewTraces()
	rs := td.ResourceSpans().AppendEmpty()
	// no service name attribute
	p := resourceToDbProcess(rs.Resource())
	assert.Equal(t, noServiceName, p.ServiceName)

	// only service name
	rs.Resource().Attributes().PutStr(otelsemconv.ServiceNameKey, "svc")
	p = resourceToDbProcess(rs.Resource())
	assert.Equal(t, "svc", p.ServiceName)
}

func TestSpec_appendTagsFromAttributes_Map(t *testing.T) {
	attrs := pcommon.NewMap()
	attrs.PutEmptyMap("m")
	got := appendTagsFromAttributes(nil, attrs)
	assert.Len(t, got, 1)
	assert.Equal(t, dbmodel.StringType, got[0].ValueType)
	assert.Equal(t, "{}", got[0].ValueString)
}
